// Better Auth storage (doc 04): sessions, linked OAuth accounts and verification tokens. EPHEMERAL by design: no
// soft delete, no versioning, rows are physically deleted by Better Auth (sign-out, expiry, account deletion), so
// these tables are listed in forbid_delete_exempt (migration 0002_auth). The account itself is `users`.
import { index, pgTable, text, uniqueIndex, uuid } from 'drizzle-orm/pg-core';

import { timestamptz } from '../columns/base.column';
import { users } from './user.table';

const authColumns = () => ({
  /** uuid v7 generated by the app (better-auth `advanced.database.generateId`). */
  id: uuid().primaryKey(),
  createdAt: timestamptz().notNull().defaultNow(),
  updatedAt: timestamptz().notNull().defaultNow(),
});

/** One row per signed-in browser. `ipAddress` keeps only the salted ip_hash (session.create hook, doc 05). */
export const authSessions = pgTable(
  'auth_sessions',
  {
    ...authColumns(),
    userId: uuid().notNull().references(() => users.id),
    token: text().notNull(),
    expiresAt: timestamptz().notNull(),
    ipAddress: text(),
    userAgent: text(),
  },
  (t) => [uniqueIndex().on(t.token), index().on(t.userId)],
);

/** Identity-provider link (Google: providerId 'google', accountId = Google `sub`). */
export const authAccounts = pgTable(
  'auth_accounts',
  {
    ...authColumns(),
    userId: uuid().notNull().references(() => users.id),
    accountId: text().notNull(),
    providerId: text().notNull(),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: timestamptz(),
    refreshTokenExpiresAt: timestamptz(),
    scope: text(),
    /** Unused (e-mail + password is disabled); part of the Better Auth model. */
    password: text(),
  },
  (t) => [uniqueIndex().on(t.providerId, t.accountId), index().on(t.userId)],
);

/** Short-lived tokens (OAuth state, etc.). */
export const authVerifications = pgTable(
  'auth_verifications',
  {
    ...authColumns(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamptz().notNull(),
  },
  (t) => [index().on(t.identifier)],
);
